package org.neo.parts;

import android.app.WallpaperManager;
import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.util.Log;

import java.io.IOException;

/**
 * Sets the Neo wallpaper (res/drawable-nodpi/neo_wallpaper.jpg, generated by
 * device/xiaomi/ingres/neo/wallpaper/make_wallpaper.py) on the home and lock screen once, when
 * the first boot completes. Later wallpaper choices are left alone.
 */
public class WallpaperInitReceiver extends BroadcastReceiver {
    private static final String TAG = "NeoParts";
    private static final String PREFS = "neo_first_boot";
    private static final String KEY_DONE = "wallpaper_set";

    @Override
    public void onReceive(Context context, Intent intent) {
        if (!Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())) {
            return;
        }
        final SharedPreferences prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        if (prefs.getBoolean(KEY_DONE, false)) {
            return;
        }
        final PendingResult result = goAsync();
        new Thread(() -> {
            try {
                WallpaperManager.getInstance(context).setResource(R.drawable.neo_wallpaper,
                        WallpaperManager.FLAG_SYSTEM | WallpaperManager.FLAG_LOCK);
                prefs.edit().putBoolean(KEY_DONE, true).apply();
                Log.i(TAG, "Neo wallpaper set on home and lock screen");
            } catch (IOException | RuntimeException e) {
                Log.w(TAG, "could not set the Neo wallpaper, will retry next boot", e);
            } finally {
                result.finish();
            }
        }, "NeoWallpaperInit").start();
    }
}
